#include <fstream>
#include <iostream>
#include <string>
int main() {
    std::ifstream file("story.txt");
    if (!file) return 1;
    std::string line;
    while (std::getline(file, line)) {
        std::cout << line << '\\n';
    }
}

#include <iostream>
