int main() {
    std::string sentence;
    std::cout << "Enter a sentence: ";
    std::getline(std::cin, sentence);
    std::cout << "You entered: " << sentence << '\\n';
}

#include <iostream>
#include <limits>
#include <string>
int main() {
    int age;
    std::string fullName;
    std::cout << "Age: ";
    if (!(std::cin >> age)) return 1;
    std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\\n');
    std::cout << "Full name: ";
    std::getline(std::cin, fullName);
    std::cout << fullName << " (" << age << ")\\n";
}

#include <iostream>
#include <sstream>
#include <string>
int main() {
    std::string record = "Mina 28";
    std::istringstream row(record);
    std::string name;
    int age = 0;
    if (row >> name >> age) {
        std::cout << name << " is " << age << '\\n';
    } else {
        std::cerr << "Invalid record\\n";
    }
}

#include <iostream>
#include <string>
int main() {
    std::string line;
    if (std::getline(std::cin, line)) {
        if (line.empty()) std::cout << "Blank line received\\n";
        else std::cout << "Text: " << line << '\\n';
    } else {
        std::cout << "No line was read\\n";
    }
}
